      en: ["Established in 1944.", "Belize's oldest protected area.", "Area: approx. 430 sq km.", "Characterized by unique pine forest."],
      es: ["Fundada en 1944.", "Área protegida más antigua de Belice.", "Superficie: aprox. 430 km².", "Conocida por sus bosques de pinos."],
      pt: ["Fundada em 1944.", "Área protegida mais antiga de Belize.", "Área: aprox. 430 km².", "Conhecida pelas florestas de pinheiros."],
      fr: ["Fondée en 1944.", "Plus ancienne zone protégée du Belize.", "Superficie : env. 430 km².", "Connue pour ses forêts de pins."],
